fixes.css:
#loader {
  animation-name: loader-strobe-soft !important;
}
@keyframes loader-strobe-soft {
  0%, 100% { background-color: rgb(255, 255, 255); }
  50% { background-color: rgb(235, 235, 235); }
}

/* Not auto-applied: an area fix changes layout. */
#loader {
  max-width: 160px;
  max-height: 120px;
}
